static cplx csub(cplx a, cplx b){ return (cplx){a.r-b.r, a.i-b.i}; }
static cplx cmul(cplx a, cplx b){ return (cplx){a.r*b.r-a.i*b.i, a.r*b.i+a.i*b.r}; }
static cplx cdiv(cplx a, cplx b){ double d=b.r*b.r+b.i*b.i; return (cplx){(a.r*b.r+a.i*b.i)/d, (a.i*b.r-a.r*b.i)/d}; }

