    const double EPS=1e-14;
    for(int col=0;col<n;col++){
        int best=col; double bestm=cmag(M[col*n+col]);
        for(int row=col+1;row<n;row++){ double m=cmag(M[row*n+col]); if(m>bestm){bestm=m;best=row;} }
        if(best!=col){ for(int j=col;j<n;j++){ cplx t=M[col*n+j]; M[col*n+j]=M[best*n+j]; M[best*n+j]=t; } }
