        for(int row=col+1;row<n;row++){
            cplx f=cdiv(M[row*n+col], M[col*n+col]);
            for(int j=col;j<n;j++){ M[row*n+j]=csub(M[row*n+j], cmul(f, M[col*n+j])); }
        }
    }
    int free=-1;
    for(int col=n-1;col>=0;col--){ if(cmag(M[col*n+col])<EPS){ free=col; break; } }
    if(free<0) free=n-1;
    double *xr=(double*)malloc((size_t)n*sizeof(double));
    double *xi=(double*)malloc((size_t)n*sizeof(double));
    memset(xr,0,(size_t)n*sizeof(double)); memset(xi,0,(size_t)n*sizeof(double));
    xr[free]=1.0;
    for(int i=free-1;i>=0;i--){
        if(cmag(M[i*n+i])<EPS) continue;
        cplx sum={0.0,0.0};
        for(int j=i+1;j<n;j++){ sum=cadd(sum, cmul(M[i*n+j], (cplx){xr[j],xi[j]})); }
        cplx t=cdiv(sum, M[i*n+i]); xr[i]=-t.r; xi[i]=-t.i;
    }
    PyObject *res = PyArray_SimpleNew(1, &n, NPY_COMPLEX128);
    npy_complex128 *rd = (npy_complex128*)PyArray_DATA((PyArrayObject*)res);
    double norm=0.0; for(int i=0;i<n;i++) norm += xr[i]*xr[i]+xi[i]*xi[i];
    norm=sqrt(norm); if(norm<1e-300) norm=1.0;
    for(int i=0;i<n;i++){ rd[i].real=xr[i]/norm; rd[i].imag=xi[i]/norm; }
    free(M); free(xr); free(xi);
    return res;
}

